// Arma un nombre de objeto ordenado y sin caracteres raros:
//   <carpeta>/<fecha>/<hora>-<nombre-del-archivo>.<extensión>
// La hora al principio evita que dos archivos con el mismo nombre se pisen.
const item = $input.item;
const archivo = item.binary?.archivo;
if (!archivo) throw new Error('No llegó ningún archivo: revisá el campo «Archivo» del formulario.');

const original = archivo.fileName ?? 'archivo';
const punto = original.lastIndexOf('.');
const ext = punto > 0 ? original.slice(punto + 1).toLowerCase().replace(/[^a-z0-9]/g, '') : '';
const base = (punto > 0 ? original.slice(0, punto) : original)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'archivo';

const ahora = $now.setZone('America/La_Paz');
const carpeta = String(item.json.carpeta ?? '').replace(/^\/+|\/+$/g, '');
const objeto = [carpeta, ahora.toFormat('yyyy-LL-dd'), `${ahora.toFormat('HHmmss')}-${base}${ext ? '.' + ext : ''}`].filter(Boolean).join('/');

return {
  json: {
    bucket: String(item.json.bucket ?? '').trim(),
    objeto,
    equipo: String(item.json.equipo ?? '').trim(),
    descripcion: String(item.json.descripcion ?? '').trim(),
    nombre_original: original,
  },
  binary: item.binary,
};

// La respuesta de Cloud Storage es el objeto que quedó guardado (su «metadata»).
// Con su bucket y su nombre se arman los dos enlaces que sirven.
const o = $json.body ?? $json;
const bucket = o.bucket;
const nombre = o.name;
// En la URL, cada parte del nombre va codificada (espacios, acentos), pero las barras se quedan.
const ruta = nombre.split('/').map(encodeURIComponent).join('/');

const bytes = Number(o.size ?? 0);
const tamano = bytes >= 1048576 ? `${(bytes / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;

return {
  json: {
    bucket,
    objeto: nombre,
    tamano,
    tipo: o.contentType ?? '',
    // Abre el archivo en el navegador a quien inició sesión con una cuenta de Google que tiene permiso en el bucket.
    enlace: `https://storage.cloud.google.com/${bucket}/${ruta}`,
    // La dirección «gs://» la usan otros servicios de Google Cloud, como Natural Language o BigQuery.
    gs: `gs://${bucket}/${nombre}`,
    equipo: $('Preparar el nombre').item.json.equipo,
  },
};

// Llega acá cuando Google rechazó el pedido (la salida de error del nodo anterior).
// Busca el código y el mensaje de Google, y suma una pista según el caso.
const e = $json.error ?? {};
const d = $json.details ?? {};
const texto = typeof e === 'string' ? e : [e.message, e.description ?? d.description].filter(Boolean).join(' · ');
let codigo = String(d.httpCode ?? e.httpCode ?? (String(e.cause?.message ?? '').match(/^(\d{3})\b/) ?? [])[1] ?? (texto.match(/\b(400|401|403|404|429)\b/) ?? [])[1] ?? '');
// Algunos nodos no traen el número: se deduce del mensaje.
if (!codigo) codigo = /not found/i.test(texto) ? '404' : /access denied|permission|forbidden/i.test(texto) ? '403' : /quota|rate limit/i.test(texto) ? '429' : '';

const PISTAS = {
  400: 'El pedido está mal armado o falta un dato. Revisá lo que mandaste.',
  401: 'La credencial no sirve: revisá el correo de la cuenta de servicio y la clave privada (copiala entera).',
  403: 'Falta permiso: habilitá la API en tu proyecto y revisá el rol de la cuenta de servicio. En HTTP Request, la credencial necesita el scope cloud-platform.',
  404: 'No existe lo que pediste: revisá el nombre del bucket, del proyecto, del dataset o de la tabla.',
  429: 'Llegaste a un límite de uso. Esperá un minuto y probá de nuevo.',
};
const pista = /billing/i.test(texto)
  ? 'El proyecto no tiene facturación activa: vinculá una cuenta de facturación en Billing.'
  : PISTAS[codigo] ?? 'Abrí la ejecución en la pestaña Executions para ver la respuesta completa de Google.';
return {
  json: {
    codigo: codigo || 'sin código',
    pista,
    detalle: texto.slice(0, 400) || 'Google no mandó detalle.',
  },
};
